import java.util.*;
import java.io.*;

public class Main {
    static int[][][][] distArr = new int[15][15][15][15];
    static int[][] cap = new int[400][400];
    static char[][] scien = new char[20][20];
    static char[][] reac = new char[20][20];
    static int[] dx = {1, 0, -1, 0};
    static int[] dy = {0, 1, 0, -1};
    static int iterCount = 3;
    static int[] visited = new int[400];
    static int n, t;
    static int reachStates[][] = new int[13][13];
    static int tempStates[][] = new int[13][13];

    static int flowAug(int cnode, int dest, int bneck) {
        if (cnode == dest) return bneck;
        if (visited[cnode] == iterCount) return 0;
        visited[cnode] = iterCount;
        for (int i = 0; i <= dest; i++) {
            if (cap[cnode][i] > 0) {
                int pushed = flowAug(i, dest, Math.min(bneck, cap[cnode][i]));
                if (pushed > 0) {
                    cap[cnode][i] -= pushed;
                    cap[i][cnode] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int nodeIdx(int x, int y) {
        return (x - 1) * n + y - 1;
    }

    static void propagate(int val) {
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= n; j++)
                tempStates[i][j] = reachStates[i][j];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (tempStates[i][j] == val) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dx[d], nj = j + dy[d];
                        if (ni > 0 && nj > 0 && ni <= n && nj <= n && reachStates[ni][nj] < val && scien[ni][nj] != 'Y') {
                            reachStates[ni][nj] = val;
                        }
                    }
                }
            }
        }
    }

    static boolean checkReach(int sx, int sy, int tx, int ty, int ix, int iy) {
        for (int i = 0; i < 100; i++) {
            for (int r = 0; r < reachStates.length; r++)
                Arrays.fill(reachStates[r], 0);
            reachStates[sx][sy] = 1;
            reachStates[ix][iy] = 2;
            propagate(1);
            if (reachStates[tx][ty] == 1) return true;
            propagate(2);
            if (reachStates[tx][ty] == 2) return false;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < 15; i++)
            for (int j = 0; j < 15; j++)
                for (int k = 0; k < 15; k++)
                    for (int l = 0; l < 15; l++)
                        distArr[i][j][k][l] = 1000000000;

        int infX = -1, infY = -1;

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            scien[i] = new char[21];
            for (int j = 1; j <= n; j++) {
                scien[i][j] = line.charAt(j - 1);
                distArr[i][j][i][j] = 0;
                if (scien[i][j] == 'Z') {
                    infX = i;
                    infY = j;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            reac[i] = new char[21];
            for (int j = 1; j <= n; j++) {
                reac[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                        if (scien[i][j] != 'Y' && scien[ni][nj] != 'Y') {
                            distArr[i][j][ni][nj] = 1;
                        }
                    }
                }
            }
        }

        for (int ki = 1; ki <= n; ki++) {
            for (int kj = 1; kj <= n; kj++) {
                for (int ii = 1; ii <= n; ii++) {
                    for (int ij = 1; ij <= n; ij++) {
                        for (int ji = 1; ji <= n; ji++) {
                            for (int jj = 1; jj <= n; jj++) {
                                distArr[ii][ij][ji][jj] = Math.min(
                                    distArr[ii][ij][ji][jj],
                                    distArr[ii][ij][ki][kj] + distArr[ki][kj][ji][jj]
                                );
                            }
                        }
                    }
                }
            }
        }

        int srcNode = n * n * 2 + 1;
        int sinkNode = n * n * 2 + 2;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (Character.isDigit(scien[i][j])) {
                    cap[srcNode][nodeIdx(i, j)] = scien[i][j] - '0';
                }
                if (Character.isDigit(reac[i][j])) {
                    cap[n * n + nodeIdx(i, j)][sinkNode] = reac[i][j] - '0';
                }
                if (Character.isDigit(scien[i][j])) {
                    for (int ki = 1; ki <= n; ki++) {
                        for (int kj = 1; kj <= n; kj++) {
                            if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                                if (Character.isDigit(reac[ki][kj]) && distArr[i][j][ki][kj] <= t && checkReach(i, j, ki, kj, infX, infY)) {
                                    cap[nodeIdx(i, j)][n * n + nodeIdx(ki, kj)] = 1000;
                                }
                            }
                        }
                    }
                }
            }
        }

        int totalFlow = 0, flowVal;
        while ((flowVal = flowAug(srcNode, sinkNode, 1000)) > 0) {
            totalFlow += flowVal;
            iterCount++;
        }

        System.out.println(totalFlow);
    }
}
